pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

const users = pm.response.json();

pm.test("Response is a non-empty array", function () {
    pm.expect(users).to.be.an("array").that.is.not.empty;
});

pm.test("Response contains user information", function () {
    users.forEach(function (user) {
        pm.expect(user).to.be.an("object");
    });
});

pm.test("Each user has id, name and email", function () {
    users.forEach(function (user) {
        pm.expect(user).to.have.all.keys(
            Object.keys(user)
        );
        pm.expect(user).to.include.keys("id", "name", "email");
        pm.expect(user.id).to.be.a("number");
        pm.expect(user.name).to.be.a("string").that.is.not.empty;
        pm.expect(user.email).to.be.a("string").that.is.not.empty;
    });
});

const selectedUser = users[0];

pm.collectionVariables.set("userId", selectedUser.id);

pm.collectionVariables.set(
    "selectedUser",
    JSON.stringify(selectedUser)
);

const user = JSON.parse(
    pm.collectionVariables.get("selectedUser")
);

const uniqueValue = Date.now();

user.name = "Updated User " + uniqueValue;
user.email = "updated" + uniqueValue + "@example.com";
user.company.name = "Updated Company " + uniqueValue;

pm.collectionVariables.set("updatedName", user.name);
pm.collectionVariables.set("updatedEmail", user.email);
pm.collectionVariables.set("updatedCompany", user.company.name);

pm.collectionVariables.set(
    "updatedBody",
    JSON.stringify(user)
);

pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

const user = pm.response.json();

pm.test("Returned ID matches saved ID", function () {
    pm.expect(user.id).to.eql(
        Number(pm.collectionVariables.get("userId"))
    );
});

pm.test("Phone is not empty", function () {
    pm.expect(user.phone).to.be.a("string").that.is.not.empty;
});

pm.test("Name matches updated name", function () {
    pm.expect(user.name).to.eql(
        pm.collectionVariables.get("updatedName")
    );
});

pm.test("Email matches updated email", function () {
    pm.expect(user.email).to.eql(
        pm.collectionVariables.get("updatedEmail")
    );
});

pm.test("Company name matches updated company", function () {
    pm.expect(user.company.name).to.eql(
        pm.collectionVariables.get("updatedCompany")
    );
});
